bloques.x:
:root {
  /* primitivos */
  --marca-500: #2e2170;
  --ambar-500: #f5a524;
  --gris-900: #17151f;
  --gris-50: #f6f6f9;
  --blanco: #ffffff;
  --esc-2: 8px;  --esc-3: 16px;
  --radio-1: 8px;

  /* semánticos, tema claro */
  --fondo-pagina: var(--gris-50);
  --fondo-tarjeta: var(--blanco);
  --texto: var(--gris-900);
  --texto-suave: #5a5868;
  --accion-fondo: var(--ambar-500);
  --accion-texto: var(--gris-900);
  --enlace: var(--marca-500);
  --borde: #d9d8e2;
}
:root[data-tema="oscuro"] {
  --fondo-pagina: #14102e;
  --fondo-tarjeta: #241a5c;
  --texto: var(--blanco);
  --texto-suave: #b9b4d6;
  --enlace: #ffc857;
  --borde: #3b2f80;
}

/* componentes: solo semánticos */
.tarjeta { background: var(--fondo-tarjeta); border: 1px solid var(--borde);
           border-radius: var(--radio-1); padding: var(--esc-3); }
.boton   { background: var(--accion-fondo); color: var(--accion-texto);
           border: 0; border-radius: var(--radio-1); padding: var(--esc-2) var(--esc-3); }

{
  "color": {
    "$type": "color",
    "ambar": { "500": { "$value": { "colorSpace": "srgb", "components": [0.9608, 0.6471, 0.1412], "hex": "#f5a524" } } },
    "azul":  { "500": { "$value": { "colorSpace": "srgb", "components": [0.1804, 0.1294, 0.4392], "hex": "#2e2170" } } }
  },
  "accion": {
    "fondo": { "$type": "color", "$value": "{color.ambar.500}" },
    "texto": { "$type": "color", "$value": "{color.azul.500}" }
  },
  "espacio": {
    "$type": "dimension",
    "m": { "$value": { "value": 1, "unit": "rem" } }
  }
}

